window.kbPageData["views/entry/k-38c5c64fdd1f1ab6"] = {"key":"entry/k-38c5c64fdd1f1ab6","state":{"route":"entry/k-38c5c64fdd1f1ab6"},"node":{"id":"k-38c5c64fdd1f1ab6","mode":"k","title":"对立事件的概率","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["事件与其对立事件的概率之和为1","对立事件的概率之和为1","对立事件的概率之和等于1"],"qs":["国考 2024 副省级 行测#74","江苏 2024 A类 行测#59","江苏 2024 C类 行测#59"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":3,"repeatPositions":0,"directorySummary":"一个事件与其对立事件互斥，且二者涵盖全部可能结果，因此它们的概率之和为 1。","review":{"definition":"一个事件与其对立事件互斥，且二者涵盖全部可能结果，因此它们的概率之和为 1。","explanation":"小张所在科室有 2 个节目，“至少有一个被选送”包括恰好入选 1 个和两个都入选两种情形。其对立事件是这 2 个节目全部落选，概率为 5/14，所以所求概率为 1－5/14＝9/14，对应 D 项。","references":[],"evidence":"至少有一个被选送参加汇演","disposition":"独立词条","basis":"据原题和解析编释。","title":"对立事件的概率","related":[],"examFocus":{"国考 2024 副省级 行测#74":"根据人数互异、下限和倍数限制确定第二大小组的规模，再用对立事件比较相应的组员选取方式数与总方式数。","江苏 2024 A类 行测#59":"用对立事件处理“至少一个入选”，比较对立情形的节目选取组合数与总组合数。","江苏 2024 C类 行测#59":"用对立事件处理“至少一个入选”，比较对立情形的节目选取组合数与总组合数。"}},"readings":[{"origin":"k-38c5c64fdd1f1ab6","title":"对立事件的概率","qs":["江苏 2024 C类 行测#59"],"definition":"一个事件与其对立事件互斥，且二者涵盖全部可能结果，因此它们的概率之和为 1。","explanation":"小张所在科室有 2 个节目，“至少有一个被选送”包括恰好入选 1 个和两个都入选两种情形。其对立事件是这 2 个节目全部落选，概率为 5/14，所以所求概率为 1－5/14＝9/14，对应 D 项。","evidence":"至少有一个被选送参加汇演","doubt":"","references":[]},{"origin":"k-4fb53c99b56f5c77","title":"对立事件的概率","qs":["江苏 2024 A类 行测#59"],"definition":"在同一次随机试验中，事件 A 与“事件 A 不发生”互为对立事件。两者恰有一个发生，概率之和为 1。","explanation":"第 59 题中，小张所在科室的两个节目至少有一个入选，包括恰好入选一个和两个都入选。它的对立事件是两个节目都落选，即选出的 3 个节目全部来自其余 6 个节目。两个节目都落选的概率为 C(6,3)/C(8,3)=5/14，因此所求概率为 1−5/14=9/14，对应 D 项。","evidence":"反面情况为3个选送节目均不来自小张所在的科室","doubt":"","references":[]},{"origin":"k-6ab403948aa552fe","title":"对立事件的概率","qs":["国考 2024 副省级 行测#74"],"definition":"一个事件及其对立事件恰好有一个发生，因此两者的概率之和为1。对立事件更容易计数时，可用1减去其概率求原事件的概率。","explanation":"最小组若有4人，六组人数至少为4至9人，总人数至少39人。因此最小组有3人，最大组至多9人。3至9这七个人数合计42，选六个合计36须舍去6，故第二大组有8人。按解析采用的等可能分组模型，随机取这8名组员时，甲乙至少一人入组选取的对立事件是两人均未入组。所求概率为1－(28/36)×(27/35)＝40%，选B。","evidence":"反面情况为甲和乙两人均未分到人数第二多的小组","doubt":"","references":[]}]},"questions":{"国考 2024 副省级 行测#74":{"paper":"国考 2024 副省级 行测","n":74,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",14],"asrc":["a475ecf57d968bc14cd6.pdf",23],"card":"aa55d9f73af733cc0b1ffa5e","links":[{"id":"k-38c5c64fdd1f1ab6","role":"解题依据","why":"两人均未进入该组的概率可用于求至少一人进入的概率。"}]},"江苏 2024 A类 行测#59":{"paper":"江苏 2024 A类 行测","n":59,"mod":"数量关系","src":["f8fec75f67d6d1ba5759.pdf",10],"asrc":["0126a1c8aceee632ea2b.pdf",17],"card":"5b1dc0b3f466e8cd25123e80","links":[{"id":"k-38c5c64fdd1f1ab6","role":"解题依据","why":"指定科室至少有一个节目入选与该科室节目全部落选互为对立事件。"}]},"江苏 2024 C类 行测#59":{"paper":"江苏 2024 C类 行测","n":59,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",10],"asrc":["02d6b49839583bdaf297.pdf",16],"card":"12be07104d0ccb37b68cde80","links":[{"id":"k-38c5c64fdd1f1ab6","role":"直接考查","why":"至少一个入选的概率可由1减去全部落选的概率得到。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-38c5c64fdd1f1ab6":[["国考 2024 副省级 行测#74"],["江苏 2024 A类 行测#59"],["江苏 2024 C类 行测#59"]]}};
